\label{thm: main1}
 Let $f\in \operatorname{Aff}(T,\omega)$ be an AIET of hyperbolic periodic type, semi-conjugated to a self-similar IET $T=(\pi,\lambda)$, with the vector of logarithms of slopes $\omega$. Let $\mu_f$ be the invariant measure of $f$. Then
 \begin{enumerate}
 \item if $\omega$ is of stable type, then $\operatorname{dim}_H(\mu_f)=1$;
 \item if $\omega$ is of central-stable type, then $0<\operatorname{dim}_H(\mu_f)<1$;
 \item if $\omega$ is of unstable type, then $\operatorname{dim}_H(\mu_f)=0$.
 \end{enumerate}

\label{thm: main2}
 Let $f\in \operatorname{Aff}(T,\omega)$ be an AIET of hyperbolic periodic type, semi-conjugated to a self-similar IET $T=(\pi,\lambda)$, with the vector of logarithms of slopes $\omega$. Let $h:I\to I$ be the semi-conjugacy between $f$ and $T$, i.e., $T\circ h=h\circ f$. Let $\mu_f$ be the invariant measure of $f$. Then the supremal H\"older exponent $\mathfrak{H}(h)$ of $h$ satisfies:
 \begin{enumerate}
 \item \label{numb:Thm 1.3 (1)}$\mathfrak{H}(h)= +\infty$, if $\omega$ is of stable type and $\alpha(\omega)=\rho_T$;
 \item \label{numb:Thm 1.3 (2)}$\mathfrak{H}(h)= 1+\frac{\alpha(\omega)}{\rho_T}$, if $\omega$ is of stable type and $\alpha(\omega)<\rho_T$;
 \item \label{numb:Thm 1.3 (3)}$0< \mathfrak{H}(h)<\operatorname{dim}_H(\mu_f)<1$, if $\omega$ is of central-stable type;                                                                                                                                                                
 \item \label{numb:Thm 1.3 (4)}$\mathfrak{H} (h)=0$, i.e. $h$ is not H\"older, if $\omega$ is of unstable type.
 \end{enumerate}

\label{thm: main4}
 Let $f\in \operatorname{Aff}(T,\omega)$ be an AIET of hyperbolic periodic type, semi-conjugated to a self-similar IET $T=(\pi,\lambda)$, with the vector of logarithms of slopes $\omega$ of either central-stable or stable type. Let $h:I\to I$ be the conjugacy between $f$ and $T$, i.e., $T\circ h=h\circ f$. Let $\nu_\omega$ be the $\phi_{\omega}$ conformal measure w.r.t.\ $T$. Then the supremal H\"older exponent $\mathfrak{H}(h^{-1})$ satisfies
 \begin{enumerate}
 \item {$\mathfrak{H}(h^{-1})= +\infty$, if $\omega$ is of stable type and $\alpha(\omega)=\rho_T$};
 \item {$\mathfrak{H}(h^{-1})= 1+\frac{\alpha(\omega)}{\rho_T}$, if $\omega$ is of stable type and $\alpha(\omega)<\rho_T$};
 \item $0< \mathfrak{H}(h^{-1})<\operatorname{dim}_H(\nu_\omega)<1$, if $\omega$ is of central-stable type.
 \end{enumerate}

\label{rem:invh}
In the case where the log-slope vector is of central-stable type, in Section~\ref{sec:regofinverse} we also provide an effective formula for $\mathfrak{H}(h^{-1})=\frac{\xi^f}{\rho_T}$ that also allows us to compute it. The quantity $\xi^f$ is determined similarly to $\zeta^f$, which we already mentioned in Remark~\ref{rem:h}.
This time the quantity $\xi^f$ is the smallest mean value of $\vartheta_-$ (mentioned in Remark~\ref{rem:h}) for all elementary loops on the directed graph $\mathfrak{G}_T$. Since the set of elementary loops is finite, the quantity $\xi^f$ can also be effectively computed.

\label{lem:uniformlimit}
Let $f$ be a periodic type GIET with period $N$ and let $\mu_f$ be its unique invariant probability measure. Let $T = (\pi, \lambda)$ be the unique self-similar IET to which $f$ is semi-conjugated, and let us denote by $\rho_T$ the logarithm of the Perron-Frobenius eigenvalue of the associated self-similarity matrix. Then

\begin{equation*}
\label{eq:uniformlimitGIET}
\lim_{k\to\infty}-\frac{1}{k}\log\mu_f\big(\mathcal Q^f_{kN}(x)\big) = \rho_T, \qquad \text{uniformly in $x \in [0,1)$.}
\end{equation*}

By \eqref{eq:invariant_lebesgue_partition}, it suffices to show that
\begin{equation}
\label{eq:uniformlimitIET}
\lim_{k\to\infty}-\frac{1}{k}\log Leb \big(\mathcal Q^T_{kN}(x)\big) = \rho_T, \qquad \text{uniformly in $x \in [0,1)$.}
\end{equation}
Fix $k \geq 1$. Recalling that $\lambda^{(kN)} = e^{-k\rho_T} \lambda$ and since $T$ is an IET, we have
\[ e^{-k\rho_T}\min_{\alpha \in {\mathcal{A}}} \lambda_\alpha = \min_{\alpha \in {\mathcal{A}}} \lambda^{(kN)}_\alpha\leq Leb \big(\mathcal Q^T_{kN}(x)\big) \leq \max_{\alpha \in {\mathcal{A}}} \lambda^{(kN)}_\alpha = e^{-k\rho_T}\max_{\alpha \in {\mathcal{A}}} \lambda_\alpha,\]
for any $x \in [0, 1).$ Equation \eqref{eq:uniformlimitIET} now follows easily from the inequality above.

Let us define an operator $\Phi$ acting on the space $\mathcal{P}(X)$ of probability measures on $X$
by the formula
\begin{equation*}
\Phi(\nu) = \frac{e^{-\phi}dT^{-1}_{*}\nu}{\int_{X} e^{-\phi}\ dT^{-1}_{*}\nu}.
\end{equation*}
As $T$ and $\phi$ are continuous, $\Phi$ is continuous in the weak-* topology on $\mathcal{P}(X)$. By Schauder-Tychonoff fixed point theorem, we obtain a measure $\mu\in \mathcal{P}(X)$ satisfying
\begin{equation}\label{eq: almostconformal}
\nu = \frac{e^{-\phi} T^{-1}_{*}{\nu}}{\int_{X} e^{-\phi}\ dT^{-1}_{*}\nu},
\end{equation}
which after taking $\Delta: = \log (\int_{X} e^{-\phi}\ dT^{-1}_{*}\nu)$, is equivalent to
\begin{equation*}
\frac{dT_*^{-1}\nu}{d\nu} = e^{\phi+\Delta}.
\end{equation*}By induction, for every $n \in \mathbb{N}$
\begin{equation}\label{formula_in_proposition}
\frac{dT_*^{-n}\nu}{d\nu} = e^{S_n(\phi+\Delta)}.
\end{equation}
Since $T$ is uniquely ergodic and $\phi$ has integral $0$, $\frac{1}{n}S_n(\phi +\Delta) $ converges uniformly to the constant $\Delta$.
Consequently, for any $\varepsilon > 0 $, we have
\begin{equation*}
e^{n(\Delta-\varepsilon)} < \int_{X} e^{S_n(\phi+\Delta)} d\mu < e^{n(\Delta+\varepsilon)},
\end{equation*}
for large enough $n$.
By \eqref{formula_in_proposition}, the middle term is equal to $1$, which gives $
\Delta = 0 $. Thus, by \eqref{eq: almostconformal}, the measure $\nu$ is $\phi$-conformal.

\label{lem:from_cs_to_c}
Let $T=(\pi,\lambda)$ be a hyperbolically self-similar IET of period $N$. Let $\omega\in{\mathbb{R}}^{{\mathcal{A}}}$ be a vector of central-stable type. Consider the unique $\omega$-conformal measure $\nu_\omega$. Let $\omega=\omega_c+\omega_s$ be the decomposition of $\omega$ into the central (invariant) and stable vector, respectively, and let $\nu_{\omega_c}$ be the unique $\omega_c$-conformal measure.
Then,
\begin{equation}\label{eq: Rnuvc}
R_*(\nu_{\omega_c}|_{R^{-1}I})=e^{-\rho_{\nu_{\omega_c}}}\nu_{\omega_c},
\end{equation}
where $R:[0,e^{-\rho_T})\to[0,1)$ is the linear rescaling given by $R(x)=e^{\rho_T}x$, $\rho_{\nu_{\omega_c}}$ is the logarithm of the Perron-Frobenius eigenvalue of the matrix $M^{(N)}_{\pi,\lambda,\omega_c}$, and the vector $(\nu_{\omega_c}(I_\alpha))_{\alpha\in\mathcal A}$ is a left Perron-Frobenius eigenvector of $M^{(N)}_{\pi,\lambda,\omega_c}$.

Moreover,
for every $x\in [0,1)$, we have
\begin{equation}\label{eq:partitiopassintocentral}
\lim_{n\to\infty}\frac{\log \nu_\omega(P_T^{(n)}{(x)})}{\log \nu_{\omega_c}(P_T^{(n)}{(x)})}=1,
\end{equation}
and there exists a constant $C>1$ such that for every $n\geq 0$ and $x\in[0,1)$, we have
\begin{equation}\label{eq:baseshaveboundedquotients}
\frac{\nu_\omega(P_T^{(n)}{(x)})}{\nu_\omega(P_T^{(n+1)}{(x)})}\leq C.
\end{equation}
If $f\in\textup{Aff}(T,\omega)$, then for every $n\geq 0$ and $x\in[0,1)$, we have
\begin{equation}\label{eq:baseshaveboundedquotients_affine}
\frac{Leb(P_f^{(n)}{(x)})}{Leb(P_f^{(n+1)}{(x)})}\leq C.
\end{equation}

Equality \eqref{eq:partitiopassintocentral} is a direct consequence of Corollary~\ref{cor: bded_density}. Indeed, it follows from the existence of $D>1$ such that
\begin{equation}\label{eq: lipschitz_relation}
 D^{-1}\le \frac{\nu_\omega(J)}{\nu_{\omega_c}(J)}\le D\qquad\text{for every}\quad J\in\mathcal P^{(n)}_T,
\end{equation}
and from the continuity of both measures proved by Proposition~\ref{prop:conformal_measures}.




To show \eqref{eq:baseshaveboundedquotients}, in view of \eqref{eq: lipschitz_relation}, it is enough to prove that there exists $C>1$ such that for every $n\geq 0$ and $x\in [0,1)$, we have
\begin{equation}\label{eq:baseshaveboundedquotients_2}
\frac{\nu_{\omega_c}(P_T^{(n)}{(x)})}{\nu_{\omega_c}(P_T^{(n+1)}{(x)})}\leq C.
\end{equation}
As $P_T^{(n)}{(x)}=T^j I^{(nN)}_\alpha$ for some $\alpha\in\mathcal A$ and $0\leq j<q^{(nN)}_\alpha$, and $P_T^{((n+1)N)}{(x)}\subset P_T^{(n)}{(x)}$, we have $P_T^{(n+1)}{(x)}=T^j(\mathcal{RV}^{nN}(T))^i(I^{((n+1)N)}_\beta)$
for some $\beta\in\mathcal A$ and $0\leq j<q^{(N)}_\beta$. As $\nu_{\omega_c}$ is a $\phi^T_{\omega_c}$-conformal measure, we have
\begin{equation}\label{eq: Pn+1 to n}
\frac{\nu_{\omega_c}(P_T^{(n)}{(x)})}{\nu_{\omega_c}(P_T^{(n+1)}{(x)})}=\frac{\nu_{\omega_c}(T^j I^{(nN)}_\alpha)}{\nu_{\omega_c}(T^j(\mathcal{RV}^{nN}(T))^iI^{((n+1)N)}_\beta)}=\frac{\nu_{\omega_c}(I^{(nN)}_\alpha)}{\nu_{\omega_c}(\mathcal{RV}^{nN}(T)^iI^{((n+1)N)}_\beta)}.
\end{equation}
Let us consider the linear rescaling $R:[0,e^{-\rho_T})\to[0,1)$ given by $R(x)=e^{\rho_T}x$. By the self-similarity of $T$, the map $R^n:I^{(nN)}\to I^{(0)}$ is a conjugaty between $\mathcal{RV}^{nN}(T)$ and $T$.

As the vector $\omega_c$ is invariant for $M^n$, the measure $\nu_{\omega_c}|_{R^{-n}I}$ restricted to $R^{-n}I=[0,e^{-n\rho_T})$ is a conformal measure for the induced IET $\mathcal{RV}^{nN}(T)$, where the potential is determined by the vector $\omega_c^{(nN)}=\omega_c M^n=\omega_c$. It follows that the image $R^n_*(\nu_{\omega_c}|_{R^{-n}I})$ is a $\phi^T_{\omega_c}$-conformal measure. By the uniqueness of the probability $\phi^T_{\omega_c}$-conformal measure (see Proposition~\ref{prop:conformal_measures}), we have
\begin{equation}\label{eq: trannuvc}
R^n_*(\nu_{\omega_c}|_{R^{-n}I})=\nu_{\omega_c}({R^{-n}I})\nu_{\omega_c}.
\end{equation}
By the definition of the matrices $M^{(n)}_{\pi,\lambda,\omega_c}$, the $\phi^T_{\omega_c}$-conformal measure $\nu_{\omega_c}$ is such that, for any $n\geq 1$, we have
\begin{equation}\label{eq: reno nu}
(\nu_{\omega_c}(I_\alpha))_{\alpha\in\mathcal A}=(\nu_{\omega_c}(I^{(nN)}_\alpha))_{\alpha\in\mathcal A}\cdot M^{(nN)}_{\pi,\lambda,\omega_c}.
\end{equation}
Note that this formula is true for any vector $\omega\in{\mathbb{R}}^{\mathcal A}$ and follows from the same arguments as \eqref{eq: renolambda}.

As $(\pi,\lambda)$ is self-similar and $\omega_c$ is a fixed vector for its self-similarity matrix $M$, by \eqref{eq: heigthcocycle} and \eqref{eq: cocycleMv}, we have
\begin{equation*}\label{eq: MnN}
M^{(nN)}_{\pi,\lambda,\omega_c}=(M^{(N)}_{\pi,\lambda,\omega_c})^n\quad\text{for any}\quad n\geq 1.
\end{equation*}
In view of \eqref{eq: trannuvc} and \eqref{eq: reno nu}, this gives
\begin{equation*}\label{eq: reno nu center}
(\nu_{\omega_c}(I_\alpha))_{\alpha\in\mathcal A}=(\nu_{\omega_c}(R^{-n}I^{(N)}_\alpha))_{\alpha\in\mathcal A}\cdot (M^{(N)}_{\pi,\lambda,\omega_c})^n=\nu_{\omega_c}(R^{-n}I)(\nu_{\omega_c}(I_\alpha))_{\alpha\in\mathcal A}\cdot (M^{(N)}_{\pi,\lambda,\omega_c})^n.
\end{equation*}
It follows that $(\nu_{\omega_c}(I_\alpha))_{\alpha\in\mathcal A}$ is a left Perron-Frobenius eigenvector for $M^{(N)}_{\pi,\lambda,\omega_c}$ and $\nu_{\omega_c}(R^{-n}I)=e^{-n\rho_{\nu_{\omega_c}}}$. In particular, by \eqref{eq: trannuvc}, we have \eqref{eq: Rnuvc}.
Since $R^n\circ\mathcal{RV}^{nN}(T)=T\circ R^n$, by \eqref{eq: Rnuvc}, we obtain that
\begin{align*}
\nu_{\omega_c}(I^{(nN)}_\alpha)&=\nu_{\omega_c}(R^{-n}I_\alpha)=e^{-n\rho_{\nu_{\omega_c}}}\nu_{\omega_c}(I_\alpha),\\
\nu_{\omega_c}(\mathcal{RV}^{nN}(T)^iI^{((n+1)N)}_\beta)&=\nu_{\omega_c}(\mathcal{RV}^{nN}(T)^iR^{-n}I^{(N)}_\beta)=\nu_{\omega_c}(R^{-n}T^iI^{(N)}_\beta)\\
&=e^{-n\rho_{\nu_{\omega_c}}}\nu_{\omega_c}(T^iI^{(N)}_\beta).
\end{align*}
Together with \eqref{eq: Pn+1 to n}, this gives
\[\frac{\nu_{\omega_c}(P_T^{(n)}{(x)})}{\nu_{\omega_c}(P_T^{(n+1)}{(x)})}=\frac{\nu_{\omega_c}(I_\alpha)}{\nu_{\omega_c}(T^iI^{(N)}_\beta)}.\]
It follows that \eqref{eq:baseshaveboundedquotients_2} holds with
\[C:=\max\big\{\nu_{\omega_c}(T^iI^{(N)}_\beta)^{-1}\mid \beta\in\mathcal A,\, 0\leq j<q^{(N)}_\beta\big\}.\]



Finally, note that since $\omega$ is of central-stable type, by \eqref{eq: isconjugated}, the AIET $f\in \textup{Aff}(T,\omega)$ is conjugated to $T$ via a homeomorphism $h$ with $h(P_f^{(n)}(x))=P_T^{(n)}(h(x))$.
Thus \eqref{eq:baseshaveboundedquotients_affine} follows directly from \eqref{eq:baseshaveboundedquotients} and \eqref{eq:projected_Lebesgue_measure 0}.
This finishes the proof.

\label{lem:adj_comparable}
Fix $1 < \delta < C$. For $m$-a.e. $x \in [0, 1)$ there exists $N_x \in {\mathbb{N}}$ such that for any $ n \geq N_x$ and any $J \in \mathcal{P}^{(n)}$ adjacent to $P^{(n)}(x)$ we have
\begin{equation}
 \label{eq:comparability}
 \delta^{-n} \leq \frac{\mu(P^{(n)}(x))}{\mu(J)}, \frac{\nu(P^{(n)}(x))}{\nu(J)} \leq \delta^n.
\end{equation}

\label{thm:HD_formula}
For $m$-a.e.\ $x\in [0,1)$, we have
\begin{equation}\label{eq:a/b}
 \lim_{\epsilon\to 0}\frac{\log \mu(x-\epsilon,x+\epsilon)}{\log \nu(x-\epsilon,x+\epsilon)}=\frac{a}{b}.
\end{equation}
In particular, if $m = \mu$ and $\nu = \operatorname{Leb}$, then $\dim_H(\mu) = \tfrac{a}{b}$.

\label{prop: centrallimit}
Assume that $\omega$ is of central-stable type.  
Then
\begin{equation}
\lim_{n\to\infty}-\frac{1}{n}\log \operatorname{Leb}\big(P^{(n)}_f(x)\big) = \mathcal{G}(T, \omega)> \rho_T\qquad\text{for $\mu_f$-a.e }x\in[0,1),
\end{equation}
where $\mathcal{G}(T, \omega)$ is given by \eqref{eq: HD_invariant_formula}.

\label{prop: unstablelimit}
Assume that $\omega$ is of unstable type. Then
\begin{equation}
\lim_{n\to\infty}-\frac{1}{n}\log \operatorname{Leb}\big(P^{(n)}_f(x)\big)=+\infty\qquad\text{for $\mu_f$-a.e }x\in[0,1).
\end{equation}

\label{prop: centrallimit_conformal}
Assume that $\omega$ is of central-stable type.  
Denote by $\nu_\omega$ the unique $\phi^T_{\omega}$-conformal measure. Then
\begin{equation}
\lim_{n\to\infty}-\frac{1}{n}\log \nu_\omega\big(P^{(n)}_T(x)\big) = \mathcal{H}(T, \omega)< \rho_T\qquad\text{for $\nu_\omega$-a.e }x\in[0,1),
\end{equation}
where $\mathcal{H}(T, \omega)$ is given by \eqref{eq: HD_conformal_formula}.

If $\omega$ is of stable type, the results follow directly from Proposition~\ref{prop:stableconj}. On the other hand, if $\omega$ is of central-stable type, the result is a direct consequence of Theorem~\ref{thm: main3}.

Assume now that $\omega$ is of unstable type. By Proposition~\ref{prop: unstablelimit}, for $\mu_f$-a.e. $x\in [0,1)$ we have
\begin{equation}\label{eq: unstableproof_1}
\lim_{n\to\infty}-\frac{1}{n}\log Leb(P^{(n)}_f(x))=\infty.
\end{equation}
Moreover, by Lemma~\ref{lem:uniformlimit}, we also have that for every $x\in[0,1)$ the following convergence holds
\begin{equation}\label{eq: unstableproof_2}
\lim_{n\to\infty}-\frac{1}{n}\log\mu_f (P^{(n)}_f(x))=\rho_T.
\end{equation}

In view of Theorem~\ref{prop: frostman_Lemma}, it is enough to find for $\mu_f$-a.e. $x\in I$, a sequence $(\epsilon_n)_{n\in{\mathbb{N}}}$, which converges to $0$ and such that
\begin{equation}\label{eq: enough for 0HD}
\lim_{n\to\infty} \frac{\log \mu (x-\epsilon_n,x+\epsilon_n)}{\log \epsilon_n}=0.
\end{equation}

Let $x\in [0,1)$ be such that \eqref{eq: unstableproof_1} is satisfied and let $\epsilon_{n}:=Leb(P^{(n)}_f(x))$. In particular, by \eqref{eq: unstableproof_1}, we have $\epsilon_n\to 0$. Then, since $P^{(n)}_f(x)\subset (x-\epsilon_n,x+\epsilon_n)$, we obtain
\[
\frac{\log \mu_f (x-\epsilon_n,x+\epsilon_n)}{\log \epsilon_n}\leq
\frac{\log \mu_f(P^{(n)}_f(x))}{\log \epsilon_n}=\frac{\log \mu_f(P^{(n)}_f(x))}{n}\cdot
\frac{n}{\log Leb (P^{(n)}_f(x))}\to 0,
\]
where the convergence follows from \eqref{eq: unstableproof_1} and \eqref{eq: unstableproof_2}. This proves \eqref{eq: enough for 0HD} and completes the proof of the theorem.

For every $t\in{\mathbb{R}}$, we have
\[\mathcal{G}(T, t\omega)=\rho(t)-t\rho'(0)\quad\text{and}\quad\mathcal{H}(T, t\omega)=\rho(t)-t\rho'(t).\]
In particular, we have
\begin{equation}\label{dim_formulas}
\dim_H(\mu_t)=\frac{\rho(0)}{\rho(t)-\rho'(0)t} \quad \text{and}\quad
	\dim_H(\nu_t)=\frac{\rho(t)-\rho'(t)t}{\rho(0)}.
\end{equation}
Moreover,
\begin{equation}\label{dim_formula}
\frac{d}{dt}\Big(\frac{1}{t\dim_H(\mu_t)}\Big)=-\frac{\dim_H(\nu_t)}{t^2}.
\end{equation}

For every $t\in{\mathbb{R}}$, let $\ell(t),\theta(t)\in{\mathbb{R}}^{\mathcal A}_{>0}$ be the left and the right Perron-Frobenius eigenvectors such that $|\ell(t)|=1$ and $\langle\ell(t),\theta(t)\rangle=1$. Then $e^{\rho(t)}=\ell(t){M}(t\omega)\theta(t)$. Since the map $t \mapsto \rho(t)$ is analytic, it is not difficult to show (using the implicit function theorem) that the maps $t \mapsto \ell(t)$ and $t \mapsto \theta(t)$ are also analytic.

Notice that
\begin{equation}\label{differentiation}
	\tfrac{d}{dt}e^{\rho(t)}=\tfrac{d}{dt} \big(\ell(t) M(t\omega)\theta(t)\big) = \ell(t) \tfrac{d}{dt}{M}(t\omega)\theta(t).
\end{equation}
Indeed, using Leibniz's product rule twice, we obtain
\begin{align*}
\tfrac{d}{dt} \big(\ell(t) M(t\omega)\theta(t)\big)&
={\ell}'(t) M(t\omega)\theta(t) + \ell(t)\tfrac{d}{dt}{M}(t\omega)\theta(t)+ \ell(t)M(t\omega) {\theta'(t)}\\
&=\ell(t)\tfrac{d}{dt}{M}(t\omega)\theta(t)+e^{\rho(t)}(\ell'(t)\theta(t)+l(t)\theta'(t))\\
&=\ell(t)\tfrac{d}{dt}{M}(t\omega)\theta(t)+e^{\rho(t)}\tfrac{d}{dt}\langle\ell(t),\theta(t)\rangle=\ell(t)\tfrac{d}{dt}{M}(t\omega)\theta(t).
\end{align*}
Observe that \eqref{eq: HD_invariant_formula} can be rewritten using \eqref{formula1} and \eqref{differentiation} in the following way:

\begin{align*}
		\mathcal{G}(T, t\omega) &= \rho(t) - e^{-\rho(0)}\sum_{\alpha \in {\mathcal{A}}}\sum_{\beta\in\mathcal{A}}\ell_{\alpha}(0)\theta_{\beta}(0)\sum_{\substack{0 \leq i < q_\alpha^{(N)} \\ \beta(\alpha,i)=\beta}} \left( tS_i \phi_{\omega}\big|_{I_\alpha^{(N)}} \right) \\
&=
		\rho(t) - te^{-\rho(0)}\sum_{\alpha \in {\mathcal{A}}}\sum_{\beta\in\mathcal{A}}\ell_{\alpha}(0)\theta_{\beta}(0)\tfrac{d}{dt}M_{\alpha,\beta}(t\omega)|_{t=0} \\
&=
\rho(t) - te^{-\rho(0)}\ell(0)\Big(\tfrac{d}{dt}M(t\omega)|_{t=0} \Big)\theta(0) \\
&
		= \rho(t) - te^{-\rho(0)}\tfrac{d}{dt}e^{\rho(t)}|_{t=0} = \rho(t)-t\rho'(0).
\end{align*}
Similarity, for \eqref{eq: HD_conformal_formula}, we have
\begin{align*}
		\mathcal{H}(T, t\omega) &= \rho(t) - e^{-\rho(t)}\sum_{\alpha \in {\mathcal{A}}}\sum_{\beta\in\mathcal{A}}\ell_{\alpha}(t)\theta_{\beta}(t)\sum_{\substack{0 \leq i < q_\alpha^{(N)} \\ \beta(\alpha,i)=\beta}} e^{tS_i \phi_{\omega}\big|_{I_\alpha^{(N)}}} \left( tS_i \phi_{\omega}\big|_{I_\alpha^{(N)}} \right)
		\\ &=
		\rho(t) - te^{-\rho(t)}\sum_{\alpha \in {\mathcal{A}}}\sum_{\beta\in\mathcal{A}}\ell_{\alpha}(t)\theta_{\beta}(t)\tfrac{d}{dt} M_{\alpha,\beta}(t\omega) \\
&=
\rho(t) - te^{-\rho(t)}\tfrac{d}{dt} e^{\rho(t)}
		=\rho(t)-t\rho'(t).
	\end{align*}
In summary, in view of \eqref{eq: both dim}, we have
\begin{equation*}
	\dim_H(\mu_t)=\frac{\rho(0)}{\rho(t)-\rho'(0)t} \quad \mbox{ and }\quad
	\dim_H(\nu_t)=\frac{\rho(t)-\rho'(t)t}{\rho(0)}.
\end{equation*}
It follows that
\begin{align*}
\frac{d}{dt}\Big(\frac{1}{t\dim_H(\mu_t)}\Big)=\frac{d}{dt}\Big(\frac{\rho(t)}{t\rho(0)}-\frac{\rho'(0)}{\rho(0)}\Big)
=-\frac{\rho(t)-\rho'(t)t}{t^2\rho(0)}=-\frac{\dim_H(\nu_t)}{t^2}.
\end{align*}

\label{lem:renmeas}
 Suppose that $\mu$ is the unique $\phi$-conformal measure, or $\mu_A\sim R^{-1}_*\mu$ and $\mu$ is ergodic for $T$.
 If $\phi\circ R=\phi_A$ then $\mu_A= R^{-1}_*\mu$. On the other hand, if $\mu_A= R^{-1}_*\mu$, then $\phi\circ R=\phi_A$, $\mu_A$-a.e.

\label{thm:perfect_zero}
 Suppose that $R_\mu:(X^\theta,\mu^\theta)\to (X^\theta,\mu^\theta)$ is ergodic and $\nu$ is the unique $\psi$-conformal measure which satisfies \eqref{eq:condlambda} with $\lambda=0$.
 Then, for $\mu$-a.e.\ $x\in X$,
 \begin{align}\label{eq:inf1}
 \begin{aligned}
 \lim_{n\to\infty}-\frac{1}{n}\log \nu(P^{(n)}(x))=H^u_\nu(R_\mu)&=-\sum_{\alpha\in \mathcal{A}}\sum_{0\leq i<q_\alpha}\log\frac{\nu(T^iR^{-1}P_\alpha)}{\nu(P_{\beta(\alpha,i)})}\theta_{\alpha,i}>0\\
 &=-\sum_{\alpha\in \mathcal{A}}\sum_{0\leq i<q_\alpha}\log\frac{\nu(T^iR^{-1}P_\alpha)}{\nu(P_{\alpha})}\theta_{\alpha,i},
 \end{aligned}
 \end{align}
 where $\theta_{\alpha,i}=\int_{T^iR^{-1}P_\alpha}\theta(x)d\mu(x)$.
 If additionally $\nu$ is $T$-invariant, then
 \begin{equation}\label{eq:rhonu}
 H^u_\nu(R_\mu)=\rho_\nu.
 \end{equation}

By \eqref{eq:infla=0} and Birkhoff's ergodic theorem, for $\mu^\theta$-a.e.\ $(x,r)\in X^\theta$ the sequence $-\frac{1}{n}\log \nu(P^{(n)}(\pi(x,r)))$ tends to the integral
 \begin{align*}
 -\int_{X^\theta}\log\frac{\nu({P}^{(1)}(\pi(x,r)))}{\nu({P}(\pi(x,r)))}d\mu^\theta(x,r)
 &=-\int_X\theta(x)\log\frac{\nu({P}^{(1)}(x))}{\nu({P}(x))}d\mu(x)\\
 &=-\sum_{\alpha\in \mathcal{A}}\sum_{0\leq i<q_\alpha}\log\frac{\nu(T^iR^{-1}P_\alpha)}{\nu(P_{\beta(\alpha,i)})}\theta_{\alpha,i},
 \end{align*}
