\label{lem:markow-chain}
Under the assumptions made in Section~\ref{sec:Markov}, the process $(\mathfrak{q}\circ R_\mu^n)_{n\in{\mathbb{Z}}}$ on $(X^\theta,\mu^\theta)$ is a stationary Markov chain. Moreover, if
\begin{equation}\label{eq:tozero}
\lim_{n\to\infty}\max_{J\in\mathcal P^{(n)}}\mu(J)=0\quad\text{and}\quad\lim_{n\to\infty}\max_{J\in\mathcal P^{(n)}}\operatorname{diam}(J)=0,
\end{equation}
then the map $\mathfrak{Q}:X^\theta\to \widehat{\Sigma}$ given by $\mathfrak{Q}(x,r)=(\mathfrak{q}(R_\mu^n(x,r)))_{n\in{\mathbb{Z}}}$ establishes a measure-preserving isomorphism between $R_\mu$ on $(X^\theta,\mu^\theta)$ and the Markov shift $\sigma$ on $(\widehat{\Sigma},\mathfrak{m})$, where $\mathfrak{m}:=\mathfrak{Q}_*(\mu^{\theta})$ is Markov measure with the transition matrix $\mathfrak M=[\mathfrak M_{(\alpha,i),(\beta,j)}]_{(\alpha,i),(\beta,j)\in\Sigma}$ given by
\begin{equation}\label{eq:trmat}
\mathfrak M_{(\alpha,i),(\beta,j)}=
\left\{
\begin{array}{cc}
0 &\text{if }\beta(\beta,j)\neq\alpha,\\
\mu\big(T^jP^{(1)}_\beta|P_\alpha\big) &\text{if }\beta(\beta,j)=\alpha.
\end{array}
\right.
\end{equation}

First note that for any pair $(\alpha_0,i_0)$, $(\alpha_1,i_1)$ in $\Sigma$, we have
\begin{equation}\label{eq:inter}
Q^{(1)}_{(\alpha_0,i_0)}\cap R^{-1}_\mu Q^{(1)}_{(\alpha_1,i_1)}=
\left\{
\begin{array}{cl}
\emptyset &\text{if }\beta(\alpha_1,i_1)\neq\alpha_0,\\
\!T^{i_0}R^{-1}T^{i_1}R^{-1}P_{\alpha_1}\times[0,\theta_{\beta(\alpha_0,i_0)})\! &\text{if }\beta(\alpha_1,i_1)=\alpha_0.
\end{array}
\right.
\end{equation}
Indeed, $(x,r)\in Q^{(1)}_{(\alpha_0,i_0)}\cap R^{-1}_\mu Q^{(1)}_{(\alpha_1,i_1)}$ iff $(x,r)\in T^{i_0}R^{-1}P_{\alpha_0}\times[0,\theta_{\beta(\alpha_0,i_0)})$ and
\begin{equation}\label{eq:seccon}
(RT^{-i_0}x,e^{-\rho_\mu}(e^{S_{(\alpha_0,i_0)}\phi} r+S^{\phi}_{(\alpha_0,i_0)}\theta))=R_\mu(x,r)\in T^{i_1}R^{-1}P_{\alpha_1}\times[0,\theta_{\beta(\alpha_1,i_1)}).
\end{equation}
Moreover, $RT^{-i_0}x\in P_{\alpha_0}$ and $RT^{-i_0}x\in T^{i_1}R^{-1}P_{\alpha_1}\subset P_{\beta(\alpha_1,i_1)}$. It follows that if $\beta(\alpha_1,i_1)\neq\alpha_0$, then the intersection is empty. Assume that $\beta(\alpha_1,i_1)=\alpha_0$. Then \eqref{eq:seccon} is equivalent to
\[x\in T^{i_0}R^{-1}T^{i_1}R^{-1}P_{\alpha_1}\text{ with }r\in e^{-S_{(\alpha_0,i_0)}\phi}(e^{\rho_\mu}[0,\theta_{\alpha_0})-S^{\phi}_{(\alpha_0,i_0)}\theta),\]
where the last interval contains $[0,\theta_{\beta(\alpha_0,i_0)})$. Indeed, as $i_0<q_{\alpha_0}$ and $\theta_A\circ R^{-1}=e^{\rho_\mu}\theta$, we have
\begin{gather*}
S^{\phi}_{(\alpha_0,i_0)}\theta+e^{S_{(\alpha_0,i_0)}\phi}\theta_{\beta(\alpha_0,i_0)}=S^{\phi}_{i_0+1}\theta|_{P^{(1)}_{\alpha_0}}
\leq S^{\phi}_{q_{\alpha_0}}\theta|_{P^{(1)}_{\alpha_0}}\\
=\theta_A|_{R^{-1}P_{\alpha_0}}=\theta_A\circ R^{-1}|_{P_{\alpha_0}}=e^{\rho_\mu}\theta_{\alpha_0}.
\end{gather*}
As $S^{\phi}_{(\alpha_0,i_0)}\theta\geq 0$, it follows that
\[[0,\theta_{\beta(\alpha_0,i_0)})\subset e^{-S_{(\alpha_0,i_0)}\phi}(e^{\rho_\mu}[0,\theta_{\alpha_0})-S^{\phi}_{(\alpha_0,i_0)}\theta).\]
This gives the second line in \eqref{eq:inter}. Moreover, using the form of the map $R_{\mu}$ (see \eqref{eq:seccon}), we also have
\[R_\mu Q^{(1)}_{(\alpha_0,i_0)}\cap Q^{(1)}_{(\alpha_1,i_1)}=T^{i_1}P^{(1)}_{\alpha_1}\times (e^{-\rho_\mu+S_{(\alpha_0,i_0)}\phi}[0,\theta_{\beta(\alpha_0,i_0)})+c).\]
Repeating the above arguments inductively, we get that for any sequence $((\alpha_j,i_j))_{j=0}^n$ in $\Sigma$ such that $\beta(\alpha_j,i_j)=\alpha_{j-1}$ for $1\leq j\leq n$, we have
\begin{align}
\label{eq:prod1}
\bigcap_{j=0}^nR_{\mu}^{-j}Q^{(1)}_{(\alpha_j,i_j)}&=T^{i_0}R^{-1}\ldots T^{i_n}R^{-1}P_{\alpha_n}\times[0,\theta_{\beta(\alpha_0,i_0)})\\
\bigcap_{j=0}^nR_{\mu}^{n-j}Q^{(1)}_{(\alpha_j,i_j)}&=T^{i_n}P^{(1)}_{\alpha_n}\times
\left(e^{-n\rho_\mu+\sum_{j=0}^{n-1}S_{(\alpha_j,i_j)}\phi}[0,\theta_{\beta(\alpha_0,i_0)})+c_n\right).
\end{align}
As $T^{i_0}R^{-1}\ldots T^{i_n}R^{-1}P_{\alpha_n}\in \mathcal{P}^{n+1}$ and the $\mu^\theta$-measure of the above two sets are equal, we get
\begin{align}
\label{eq:width}
\operatorname{width}\Big(\bigcap_{j=0}^nR_{\mu}^{-j}Q^{(1)}_{(\alpha_j,i_j)}\Big)&\leq \max_{J\in\mathcal P^{(n+1)}}\operatorname{diam}(J),\\
\label{eq:hight}
\operatorname{height}\Big(\bigcap_{j=0}^nR_{\mu}^{n-j}Q^{(1)}_{(\alpha_j,i_j)}\Big)&\leq \frac{\max_{\alpha\in\mathcal{A}}\theta_\alpha}{\min_{J\in\mathcal{P}^{(1)}}\mu(J)}
\max_{J\in\mathcal P^{(n+1)}}\mu(J).
\end{align}
In view of \eqref{eq:prod1}, we have
\begin{align*}
&\mu^{\theta}\left(\mathfrak{q}\circ R_\mu^{n} \in (\alpha_{n},i_{n}) \Bigm| \bigcap_{j=0}^{n-1} \mathfrak{q}\circ R_\mu^{j} \in (\alpha_{j},i_{j})\right)=
\frac{\mu^\theta\left(\bigcap_{j=0}^{n}R_{\mu}^{-j}Q^{(1)}_{(\alpha_j,i_j)}\right)}{\mu^\theta\left(\bigcap_{j=0}^{n-1}R_{\mu}^{-j}Q^{(1)}_{(\alpha_j,i_j)}\right)}\\
&=\frac{\mu^\theta\left(T^{i_0}R^{-1}\ldots T^{i_n}R^{-1}P_{\alpha_n}\times[0,\theta_{\beta(\alpha_0,i_0)})\right)}{\mu^\theta\left(T^{i_0}R^{-1}\ldots T^{i_{n-1}}R^{-1}P_{\alpha_{n-1}}\times[0,\theta_{\beta(\alpha_0,i_0)})\right)}
=\frac{\mu\left(T^{i_0}R^{-1}\ldots T^{i_n}R^{-1}P_{\alpha_n}\right)}{\mu\left(T^{i_0}R^{-1}\ldots T^{i_{n-1}}R^{-1}P_{\alpha_{n-1}}\right)}.
\end{align*}
Recall that for any $0\leq l< k\leq n$ we have $T^{i_{l+1}}R^{-1}\ldots T^{i_k}R^{-1}P_{\alpha_k}\subset P_{\beta(\alpha_{l+1},i_{l+1})}=P_{\alpha_{i_l}}$. Then $R^{-1}T^{i_{l+1}}R^{-1}\ldots T^{i_k}R^{-1}P_{\alpha_k}\subset P^{(1)}_{\alpha_{i_l}}$, and hence, by $(R^{-1})_*\mu=e^{-\rho_\mu}\mu|_{A}$, we have
\begin{align*}
\mu\left(T^{i_{l}}R^{-1}T^{i_{l+1}}R^{-1}\ldots T^{i_k}R^{-1}P_{\alpha_k}\right)&=e^{S_{(\alpha_l,i_l)}\phi}
\mu\left(R^{-1}T^{i_{l+1}}R^{-1}\ldots T^{i_k}R^{-1}P_{\alpha_k}\right)\\
&=e^{-\rho_\mu+S_{(\alpha_l,i_l)}\phi}
\mu\left(T^{i_{l+1}}R^{-1}\ldots T^{i_k}R^{-1}P_{\alpha_k}\right).
\end{align*}
It follows that
\[\frac{\mu\left(T^{i_0}R^{-1}\ldots T^{i_n}R^{-1}P_{\alpha_n}\right)}{\mu\left(T^{i_0}R^{-1}\ldots T^{i_{n-1}}R^{-1}P_{\alpha_{n-1}}\right)}
=\frac{\mu\left( T^{i_n}R^{-1}P_{\alpha_n}\right)}{\mu\left( P_{\alpha_{n-1}}\right)}=\mu(T^{i_n}P^{(1)}_{\alpha_n}|P_{\alpha_{n-1}}).\]
This shows that $(\mathfrak{q}\circ R_\mu^n)_{n\in{\mathbb{Z}}}$ on $(X^\theta,\mu^\theta)$ is a stationary Markov chain with the transition matrix given by \eqref{eq:trmat}.


Suppose that the condition \eqref{eq:tozero} holds. Then, by \eqref{eq:width} and \eqref{eq:hight}, for any sequence $\big((\alpha_j,i_j)\big)_{j\in{\mathbb{Z}}}$ in $\widehat \Sigma$, this gives
\[\lim_{n\to\infty}\operatorname{diam}\Big(\bigcap_{j=-n}^nR_{\mu}^{-j}Q^{(1)}_{(\alpha_j,i_j)}\Big)=0.\]
It follows that $\mathfrak{Q}:(X^\theta,\mu^\theta)\to (\widehat{\Sigma},\mathfrak{m})$ is a measure-preserving isomorphism.

Since $\lim_{x\to 1^-}h(x)=1$, the map $h^{-1}$ is uniformly continuous. Hence, since $\max_{J\in \mathcal P^{(n)}} Leb(h(J))$ decays exponentially with $n$, we have
\begin{equation}\label{eq:lentozero}
\lim_{n\to\infty}\max\{Leb(J)\mid J\in \mathcal P^{(n)}\}=0.
\end{equation}

Let $N$ be a natural number such that
\[\frac{-\log 2+(n-1)\rho_{\mu_f}}{n\cdot \zeta_n -\log \left(\min_{J\in \mathcal{P}^{(0)}}Leb(J)\right)}>\gamma\quad \text{for all}\quad n>N.\]
Let $\delta=\delta_N:=\min\{Leb(J)\mid J\in \mathcal P^{(N)}\}>0$. In view of \eqref{eq:lentozero}, there exists $n> N$ such that
\[
n:=\min\{m\in \mathbb N\mid \#\{[x,y]\cap \partial \mathcal P^{(m)}\}\ge 2 \},
\]
for any $x<y$ such that $|x-y|<\delta$.
Then there exist intervals $I^{-}_{n-1},I^{+}_{n-1}\in \mathcal P^{(n-1)}$ and an interval $I_{n}\in \mathcal P^{(n)}$ such that
\begin{equation}\label{eq: intervalinclusion}
 I_{n}\subseteq [x,y]\subseteq I^{-}_{n-1}\cup I^{+}_{n-1}.
 \end{equation}
We want to prove that for every $0<\gamma< \frac{\rho_{\mu_f}}{\zeta}$, we have
\begin{equation}\label{eq: Holder goal}
|h(x)-h(y)|\le |x-y|^{\gamma}\quad \text{for all $x,y$ such that}\quad |x-y|<\delta,
\end{equation}
which by \eqref{eq:projected_invariant_measure} is equivalent to
\begin{equation}\label{eq: Holder reduction}
\frac{-\log\mu_f([x,y])}{-\log Leb([x,y])}\ge \gamma,
\end{equation}
where $\mu_f$ is the unique probability $f$-invariant measure.
To prove the above inequality, we will prove that for every sufficiently small $\epsilon>0$ there exists $N$ large enough such that for every $x<y$ satisfying $|x-y|<\delta_N$, the following holds
\begin{equation}\label{eq: second Holder reduction}
 \frac{-\log\mu_f([x,y])}{-\log Leb([x,y])}\ge \frac{\rho_{\mu_f}}{\zeta}-\epsilon.
 \end{equation}
By, \eqref{eq: intervalinclusion}, we have that
\begin{align}\label{eq: Holder numerator estimate}
\begin{aligned}
-\log\mu_f([x,y])&\ge -\log \mu_f(I^{-}_{n-1}\cup I^{+}_{n-1})\ge -\log(2\cdot e^{-(n-1)\rho_{\mu_f}}\cdot \max_{J\in\mathcal P^{(0)}}\mu(J))\\
&\ge-\log 2+(n-1)\rho_{\mu_f}.
\end{aligned}
\end{align}
For any $x_0\in I_n$, we have $I_{n}=\mathcal{P}^{(n)}(x_0)$. Then, in view of \eqref{eq:infla=0}, for any choice $(x_0,r)\in I^\theta$, we have
\begin{align}\label{eq: Holder denominator estimate}
 \begin{split}
 -\log Leb([x,y])&\le -\log Leb(I_n)= -\log \nu({P}^{(n)}(x_0))\\
& =-\sum_{0\leq i<n}\log\frac{\nu({P}^{(1)}(\pi(R^i_\mu(x_0,r))))}{\nu({P}(\pi(R^{i}_\mu(x_0,r))))}-\log \nu({P}(x_0))\\
&\leq n\cdot \zeta_n-\log \left(\min_{J\in \mathcal{P}^{(0)}}Leb(J)\right).
 \end{split}
 \end{align}
By combining \eqref{eq: Holder numerator estimate} and \eqref{eq: Holder denominator estimate}, we get
\[
\frac{-\log\mu([x,y])}{-\log Leb([x,y])}\ge \frac{-\log 2+(n-1)\rho_{\mu_f}}{n\cdot \zeta_n -\log \left(\min_{J\in \mathcal{P}^{(0)}}Leb(J)\right)},
\]
with $n>N$. By the choice of $N$, we have
\[\frac{-\log 2+(n-1)\rho_{\mu_f}}{n\cdot \zeta_n -\log \left(\min_{J\in \mathcal{P}^{(0)}}Leb(J)\right)}>\frac{\rho_{\mu_f}}{\zeta}-\epsilon=\gamma\quad \text{for all}\quad n>N,\]
by taking $\epsilon:= \frac{\rho_{\mu_f}}{\zeta}-\gamma>0$.
Hence, we get \eqref{eq: Holder reduction}, whenever $|x-y|<\delta_N$ and \eqref{eq: Holder goal} with $\delta=\delta_N$. It follows that taking $C:=(1+\delta^{-1})^{1-\gamma}$, we have
\begin{equation}\label{eq:finHol}
|h(x)-h(y)|\leq C|x-y|^\gamma\quad \text{for all}\quad x,y\in[0,1).
\end{equation}
Indeed, if $x<y$ and $|x-y|\geq \delta_N$, then we choose $x=x_0<x_1<\ldots<x_{k-1}<x_k=y$ such that $|x_j-x_{j-1}|=|x-y|/k$ for all $1\leq j\leq k$ and $|x-y|/k<\delta_N\leq |x-y|/(k-1)$. Then
\[|h(x)-h(y)|\leq \sum_{j=1}^k|h(x_j)-h(x_{j-1})|\leq \sum_{j=1}^k|x_j-x_{j-1}|^{\gamma}=k\Big(\frac{|x-y|}{k}\Big)^\gamma=k^{1-\gamma}|x-y|^\gamma.\]
As $\delta_N\leq |x-y|/(k-1)\leq 1/(k-1)$, we have $k\leq 1+\delta_N^{-1}$, which gives \eqref{eq:finHol}.

\label{prop:optH}
There exists an infinite sequence of intervals $[x_n,y_n]\subset I$, such that
\begin{equation}\label{eq:limfrlog}
\lim_{n\to\infty}|x_n-y_n|=0\quad\text{and}\quad\lim_{n\to\infty}\frac{-\log\mu_f([x_n,y_n])}{-\log Leb([x_n,y_n])}=\frac{\rho_{\mu_f}}{\zeta}.
\end{equation}

As the set of elementary loops $\mathcal{C}^{el}_T$ is finite, the previous lemma gives an effective formula for counting the quantity $\zeta^f$:
\begin{equation}
\zeta^f=\zeta(\vartheta_-)=\max_{C\in \mathcal{C}^{el}_T}\frac{\vartheta_-(C)}{|C|}.
\end{equation}

\label{lem:maxcyl}
Let $\lambda$ be a $\sigma$-invariant ergodic measure on $\widehat\Sigma$ which maximizes the integral of $\vartheta$, i.e.\ $\int_{\widehat\Sigma}\vartheta\,d\lambda=\zeta(\vartheta)$.
If $C$ is a cyclic path such that $\lambda([C])>0$, then the path $C\in \mathcal{C}_T$ is $\vartheta$-maximizing i.e.\ $\frac{\vartheta(C)}{|C|}=\zeta_{\mathcal{C}}(\vartheta)$.

\label{prop:zeta0}
Let $T=(\pi,\lambda)$ be a self-similar IET of $d\ge 2$ intervals and let $M$ be its positive self-similarity matrix. Suppose that $\omega\neq 0$ is an invariant vector of the matrix $M$.
Let $\lambda$ be a $\sigma$-invariant ergodic measure on $\widehat\Sigma$ such that $\lambda([\varrho])>0$ for any $\varrho\in \Pi_T$. Then $\int_{\widehat\Sigma}\vartheta\,d\lambda<\zeta(\vartheta)$.

Suppose that, contrary to our claim, $\int_{\widehat\Sigma}\vartheta\,d\lambda=\zeta(\vartheta)$.


We will show that for any $n\geq 1$ and $\alpha^{(0)},\alpha^{(n)}\in\mathcal A$ if $f^{i_1}I^{(n)}_{\alpha^{(n)}}\subset I^{(0)}_{\alpha^{(0)}}$ and $f^{i_2}I^{(n)}_{\alpha^{(n)}}\subset I^{(0)}_{\alpha^{(0)}}$ for some $0\leq i_1<i_2<q^{(n)}_{\alpha^{(n)}}$, then $Leb(f^{i_1}I^{(n)}_{\alpha^{(n)}})=Leb(f^{i_2}I^{(n)}_{\alpha^{(n)}})$.


Take any $x_1\in f^{i_1}I^{(n)}_{\alpha^{(n)}}$ and $x_2\in f^{i_2}I^{(n)}_{\alpha^{(n)}}$. Let $(\alpha_1^{(j)},i_1^{(j)})_{j=1}^n$ and $(\alpha_2^{(j)},i_2^{(j)})_{j=1}^n$ be sequences in $\Sigma$ such that taking any $r\in[0,\theta_{\alpha^{(0)}}]$ and $\alpha^{(0)}_1=\alpha^{(0)}_2=\alpha^{(0)}$, we have
\begin{gather*}
P^{(0)}(\pi(R^j_{\mu_f}(x_1,r)))=I^{(0)}_{\alpha_1^{(j)}}, \quad P^{(0)}(\pi(R^j_{\mu_f}(x_2,r)))=I^{(0)}_{\alpha_2^{(j)}}\quad \text{for}\quad 0\leq j\leq n \\
P^{(1)}(\pi(R^{j-1}_{\mu_f}(x_1,r)))=f^{i_1^{(j)}}I^{(1)}_{\alpha_1^{(j)}},\quad P^{(1)}(\pi(R^{j-1}_{\mu_f}(x_2,r)))=f^{i_2^{(j)}}I^{(1)}_{\alpha_2^{(j)}}\quad \text{for}\quad 1\leq j\leq n.
\end{gather*}
Then $\beta(\alpha^{(j)}_1,i^{(j)}_1)=\alpha^{(j-1)}_1$ and $\beta(\alpha^{(j)}_2,i^{(j)}_2)=\alpha^{(j-1)}_2$ for $1\leq j\leq n$ and $\alpha^{(n)}_1=\alpha^{(n)}_2=\alpha^{(n)}$. As the incidence matrix for the renormalization map $R_{\mu_f}$ is positive, we can choose $(\alpha^{(n+1)},i^{(n+1)})\in\Sigma$ such that $\beta(\alpha^{(n+1)},i^{(n+1)})=\alpha^{(n)}$ and $0\leq i_1^{(0)},i_2^{(0)}<q_{\alpha^{(0)}}$ such that $\beta(\alpha_1^{(0)},i_1^{(0)})=\alpha^{(n+1)}$ and $\beta(\alpha_2^{(0)},i_2^{(0)})=\alpha^{(n+1)}$, thus obtaining two loops.


As $\vartheta=\vartheta_\pm$, in view of \eqref{eq:infla=0}, we have
\begin{align*}
\pm\log\frac{\big|f^{i_1}I^{(n)}_{\alpha^{(n)}}\big|}{\big|I^{(0)}_{\alpha^{(0)}}\big|}=\pm\sum_{j=1}^n\log\frac{\big|f^{i^{(j)}_1}I^{(1)}_{\alpha_1^{(j)}}\big|}{\big|I^{(0)}_{\alpha_1^{(j-1)}}\big|}=
\sum_{j=1}^n\vartheta\big((\alpha_1^{(j-1)},i^{(j-1)}_1)\to(\alpha_1^{(j)},i^{(j)}_1)\big),\\
\pm\log\frac{|f^{i_2}I^{(n)}_{\alpha^{(n)}}|}{|I^{(0)}_{\alpha^{(0)}}|}=\pm\sum_{j=1}^n\log\frac{|f^{i^{(j)}_2}I^{(1)}_{\alpha_1^{(j)}}|}{|I^{(0)}_{\alpha_2^{(j-1)}}|}=
\sum_{j=1}^n\vartheta\big((\alpha_2^{(j-1)},i^{(j-1)}_2)\to(\alpha_2^{(j)},i^{(j)}_2)\big).
\end{align*}
Let us consider two cyclic paths $C^1$, $C^2$ in $\mathcal{C}_T$ given respectively by
\begin{align*}
(\alpha_1^{(0)},i^{(0)}_1)\to(\alpha_1^{(1)},i^{(1)}_1)\to\cdots\to(\alpha_1^{(n)},i^{(n)}_1)\to(\alpha^{(n+1)},i^{(n+1)})\to(\alpha_1^{(0)},i^{(0)}_1),\\
(\alpha_2^{(0)},i^{(0)}_2)\to(\alpha_2^{(1)},i^{(1)}_2)\to\cdots\to(\alpha_2^{(n)},i^{(n)}_2)\to(\alpha^{(n+1)},i^{(n+1)})\to(\alpha_2^{(0)},i^{(0)}_2).
\end{align*}
Then
\begin{align*}
\vartheta(C^1)&=\sum_{j=1}^n\vartheta\big((\alpha_1^{(j-1)},i^{(j-1)}_1)\to(\alpha_1^{(j)},i^{(j)}_1)\big)\\
&\quad +\vartheta\big((\alpha_1^{(n)},i^{(n)}_1)\to(\alpha^{(n+1)},i^{(n+1)})\big)+
\vartheta\big((\alpha^{(n+1)},i^{(n+1)})\to(\alpha_1^{(0)},i^{(0)}_1)\big)\\
& = \pm\log\frac{\big|f^{i_1}I^{(n)}_{\alpha^{(n)}}\big|}{\big|I^{(0)}_{\alpha^{(0)}}\big|} \pm\log\frac{\big|f^{i^{(n+1)}}I^{(1)}_{\alpha^{(n+1)}}\big|}{\big|I^{(0)}_{\alpha^{(n)}}\big|}\pm\log\frac{\big|f^{i^{(0)}_1}I^{(1)}_{\alpha_1^{(0)}}\big|}{\big|I^{(0)}_{\alpha^{(n+1)}}\big|},
\end{align*}
and similarly
\begin{align*}
\vartheta(C^2) = \pm\log\frac{\big|f^{i_2}I^{(n)}_{\alpha^{(n)}}\big|}{\big|I^{(0)}_{\alpha^{(0)}}\big|} \pm\log\frac{\big|f^{i^{(n+1)}}I^{(1)}_{\alpha^{(n+1)}}\big|}{\big|I^{(0)}_{\alpha^{(n)}}\big|}\pm\log\frac{\big|f^{i^{(0)}_2}I^{(1)}_{\alpha_2^{(0)}}\big|}{\big|I^{(0)}_{\alpha^{(n+1)}}\big|}.
\end{align*}
As by assumption $\lambda([C^1])$, $\lambda([C^2])$ are positive, by Lemma~\ref{lem:maxcyl}, we have
\[\vartheta(C^1)=\vartheta(C^2)=(n+2)\zeta(\vartheta).\]
In view of the previous two formulas for $\vartheta(C^1)$ and $\vartheta(C^2)$, this gives
\begin{equation}\label{eq:pairs}
\big|f^{i_1}I^{(n)}_{\alpha^{(n)}}\big| \big|f^{i^{(0)}_1}I^{(1)}_{\alpha_1^{(0)}}\big| = \big|f^{i_2}I^{(n)}_{\alpha^{(n)}}\big| \big| f^{i^{(0)}_2}I^{(1)}_{\alpha_2^{(0)}} \big| .
\end{equation}


We will repeat the same argument for shorter paths. As the incidence matrix for the renormalization map $R_{\mu_f}$ is positive, we can choose $\underline{i}^{(n+1)}$ such that $(\alpha^{(n+1)},\underline{i}^{(n+1)})\in\Sigma$ and $\beta(\alpha^{(n+1)},\underline{i}^{(n+1)})=\alpha^{(0)}$. Let's consider two short cyclic paths
\begin{gather*}
\underline{C}^1=\Big((\alpha_1^{(0)},i^{(0)}_1)\to(\alpha^{(n+1)},\underline{i}^{(n+1)})\to(\alpha_1^{(0)},i^{(0)}_1)\Big),\\
\underline{C}^2=\Big((\alpha_2^{(0)},i^{(0)}_2)\to(\alpha^{(n+1)},\underline{i}^{(n+1)})\to(\alpha_2^{(0)},i^{(0)}_2)\Big).
\end{gather*}
As by assumption $\lambda([\underline{C}^1])$, $\lambda([\underline{C}^2])$ are positive, by Lemma~\ref{lem:maxcyl}, we have
$\vartheta(\underline{C}^1)=\vartheta(\underline{C}^2)=2\zeta(\vartheta)$. As
\begin{gather*}
\vartheta(\underline{C}^1)=\pm\log\frac{\big|f^{\underline{i}^{(n+1)}}I^{(1)}_{\alpha^{(n+1)}}\big|}{\big|I^{(0)}_{\alpha^{(0)}}\big|}\pm\log\frac{\big|f^{i^{(0)}_1}I^{(1)}_{\alpha_1^{(0)}}\big|}{\big|I^{(0)}_{\alpha^{(n+1)}}\big|},\\
\vartheta(\underline{C}^2)=
\pm\log\frac{\big|f^{\underline{i}^{(n+1)}}I^{(1)}_{\alpha^{(n+1)}}\big|}{\big|I^{(0)}_{\alpha^{(0)}}\big|}\pm\log\frac{\big|f^{i^{(0)}_2}I^{(1)}_{\alpha_2^{(0)}}\big|}{\big|I^{(0)}_{\alpha^{(n+1)}}\big|},
\end{gather*}
this gives $\big|f^{i^{(0)}_1}I^{(1)}_{\alpha^{(0)}}\big|=\big|f^{i^{(0)}_2}I^{(1)}_{\alpha^{(0)}}\big|$. In view of \eqref{eq:pairs}, we have
\[\big|f^{i_1}I^{(n)}_{\alpha^{(n)}}\big|=\big|f^{i_2}I^{(n)}_{\alpha^{(n)}}\big|\quad\text{whenever}\quad f^{i_1}I^{(n)}_{\alpha^{(n)}}\subset I^{(0)}_{\alpha^{(0)}}\quad\text{and}\quad f^{i_2}I^{(n)}_{\alpha^{(n)}}\subset I^{(0)}_{\alpha^{(0)}}.\]
It follows that for any $n\geq 1$ the map $g^{Leb}_{I^{(n)}}:[0,1]^\theta\to{\mathbb{R}}_{\geq 0}$ given by \eqref{def:gA} is zero. Therefore, by Lemma~\ref{lem:Xn}, the Lebesgue measure on $[0,1]$ is $f$-invariant, which is in contradiction with the non-triviality of the log-slope vector $\omega$. This shows that $\int_{\widehat\Sigma}\vartheta\,d\lambda<\zeta(\vartheta)$.

\label{lem:holder_upper_bound}
Let $\nu$ be any Borel probability on ${\mathbb{R}}$ such that for some $x_0\in I$ inequality $\liminf_{\epsilon \rightarrow 0 } \frac{\log \nu[x_0-\epsilon, x_0+\epsilon)}{\log \epsilon} \leq \alpha$ holds for some $\alpha > 0 $. Then the distribution function given by the formula $h(y)=\nu[0,y)$ has H\"older exponent bounded from above by $\alpha$. In particular, if $\operatorname{dim}_H(\nu)=0$, then $h$ is not H\"older.
\begin{proof}
 Suppose that for some $\gamma>0$
 $h$ is $\gamma$-H\"older i.e. there exist $C>0$ such that
 \begin{equation*}
 \nu[x,y) = h(y)-h(x) < C(y-x)^{\gamma},
 \end{equation*}
 holds for all $x<y \in I$. In particular, by taking logarithm, we get
 \begin{equation*}
 \log \nu[x_0-\varepsilon,x_0+\varepsilon) <\log (C(2\varepsilon)^{\gamma})=\gamma\log(2\varepsilon)+\log(C),
 \end{equation*}
 for sufficiently small $\varepsilon>0 $.
 Dividing both sides by $\log(2\varepsilon)<0$ gives
 \begin{equation*}
 \frac{\log \nu[x_0-\varepsilon,x_0+\varepsilon)}{\log(2\varepsilon)} > \gamma+\frac{\log(C)}{\log(2\varepsilon)},
 \end{equation*}
 which, after passing to the limit as $\varepsilon \rightarrow 0 $, yields $\alpha \geq \gamma$.
\end{proof}

Suppose that for some $\gamma>0$
 $h$ is $\gamma$-H\"older i.e. there exist $C>0$ such that
 \begin{equation*}
 \nu[x,y) = h(y)-h(x) < C(y-x)^{\gamma},
 \end{equation*}
 holds for all $x<y \in I$. In particular, by taking logarithm, we get
 \begin{equation*}
 \log \nu[x_0-\varepsilon,x_0+\varepsilon) <\log (C(2\varepsilon)^{\gamma})=\gamma\log(2\varepsilon)+\log(C),
 \end{equation*}
 for sufficiently small $\varepsilon>0 $.
 Dividing both sides by $\log(2\varepsilon)<0$ gives
 \begin{equation*}
 \frac{\log \nu[x_0-\varepsilon,x_0+\varepsilon)}{\log(2\varepsilon)} > \gamma+\frac{\log(C)}{\log(2\varepsilon)},
 \end{equation*}
 which, after passing to the limit as $\varepsilon \rightarrow 0 $, yields $\alpha \geq \gamma$.

If $\omega$ is of unstable type, any semi-conjugacy between $f$ and $(\pi, \lambda)$ is not H\"older continuous.
\begin{proof}
 Since we have $h_*\mu_f = Leb$ and $h$ is a non-decreasing surjection, the semi-conjugacy $h:I\rightarrow I$ is a distribution function of the measure $\mu_f$, i.e., it is given by the formula $h(x)=\mu_f[0,x)$. Since by case (3) in Theorem~\ref{thm: main1}, we have $\operatorname{dim}(\mu_f)=0$,
 the claim follows from Lemma~\ref{lem:holder_upper_bound}.
\end{proof}

Let $N$ be a natural number large enough, to be specified later. Let
\[\delta=\delta_N:=\min\{|J|\mid J\in \mathcal Q^{(N)}\}=e^{-N\rho_T}\min\{|I_{\alpha}|\mid \alpha\in \mathcal A\}>0.\]
Since
\[\max\{|J|\mid J\in \mathcal Q^{(n)}\}=e^{-n\rho_T}\max\{|I_{\alpha}|\mid \alpha\in \mathcal A\}\to 0\quad{as}\quad n\to\infty,\]
for any $x<y$ with $|x-y|<\delta$ there exists $n> N$ such that
\[
n:=\min\{m\in \mathbb N\mid \#\{[x,y]\cap \partial \mathcal P^{(m)}\}\ge 2 \}.
\]
Then there exist intervals $I^{-}_{n-1},I^{+}_{n-1}\in \mathcal Q^{(n-1)}$ and an interval $I_{n}\in \mathcal Q^{(n)}$ such that
\begin{equation}\label{eq: intervalinclusion1}
 I_{n}\subseteq [x,y]\subseteq I^{-}_{n-1}\cup I^{+}_{n-1}.
 \end{equation}
We want to prove that for every $0<\gamma< \frac{\xi}{\rho_{T}}$, we have
\begin{equation*}\label{eq: Holder goal1}
|h^{-1}(x)-h^{-1}(y)|\le |x-y|^{\gamma}\quad \text{for all $x,y$ such that}\quad |x-y|<\delta,
\end{equation*}
which is equivalent to
\begin{equation*}\label{eq: Holder reduction1}
\frac{-\log\nu([x,y])}{-\log Leb([x,y])}\ge \gamma,
\end{equation*}
where $\nu$ is the unique probability $\phi_\omega$-conformal measure.
To prove the above inequality, we will prove that for every sufficiently small $\epsilon>0$ there exists $N$ large enough such that for every $x<y$ satisfying $|x-y|<\delta_N$, the following holds
\begin{equation}\label{eq: second Holder reduction1}
 \frac{-\log\nu([x,y])}{-\log Leb([x,y])}\ge \frac{\xi}{\rho_{T}}-\epsilon.
 \end{equation}
First note that
\begin{align}\label{eq: Holder numerator estimate1}
\begin{aligned}
-\log Leb([x,y])&\leq -\log Leb(I_{n})\leq -\log(e^{-n\rho_{T}}\cdot \min_{\alpha\in\mathcal A}|I_\alpha|)\\
&=n\rho_{T}+\max_{\alpha\in\mathcal A}\log|I_\alpha|^{-1}.
\end{aligned}
\end{align}
For any $x_0\in I^{\pm}_{n-1}$, we have $I^{\pm}_{n-1}={Q}^{(n-1)}(x_0)$. Moreover, in view of \eqref{eq:infla=0}, for any choice $(x_0,r)\in I^\theta$, we have
\begin{align*}
 -\log \nu({Q}^{(n-1)}(x_0))
& =-\sum_{0\leq i<n-1}\log\frac{\nu({Q}^{(1)}(\pi(R^i_\nu(x_0,r))))}{\nu({Q}(\pi(R^{i}_\nu(x_0,r))))}-\log \nu({Q}(x_0))\\
&\geq (n-1) \xi_{n-1}.
 \end{align*}
It follows that
\begin{equation}\label{eq: Holder denominator estimate1}
-\log \nu([x,y])\geq -\log 2\cdot \max \{\nu(I^+_{n-1}),\nu(I^-_{n-1})\}\geq -\log 2+ (n-1) \xi_{n-1}.
\end{equation}
By combining \eqref{eq: Holder numerator estimate1} and \eqref{eq: Holder denominator estimate1}, we get
\[
\frac{-\log\nu([x,y])}{-\log Leb([x,y])}\geq \frac{ -\log 2+ (n-1) \xi_{n-1}}{n\rho_{T}+\max_{\alpha\in\mathcal A}\log|I_\alpha|^{-1}},
\]
with $n>N$. Choose $N$ large enough such that
\[\frac{ -\log 2+ (n-1) \xi_{n-1}}{n\rho_{T}+\max_{\alpha\in\mathcal A}\log|I_\alpha|^{-1}}>\frac{\xi}{\rho_{T}}-\epsilon=\gamma\quad \text{for all}\quad n>N,\]
by taking $\epsilon:= \frac{\xi}{\rho_{T}}-\gamma>0$.
Hence, we get $|h^{-1}(x)-h^{-1}(y)|\leq |x-y|^\gamma$, whenever $|x-y|<\delta_N$. Following the arguments from the end of the proof of Proposition~\ref{prop: centralHolderestimate}, we get
\begin{equation*}\label{eq:finHol_inv}
|h^{-1}(x)-h^{-1}(y)|\leq (1+\delta^{-1})^{1-\gamma}|x-y|^\gamma\quad \text{for all}\quad x,y\in[0,1).
\end{equation*}

